review_comment:
A minimum select code looks like this:


<details><summary>Details</summary>
<p>


```python
"""Single-select arrow-key menu using only stdlib."""

from __future__ import annotations

import sys

import click

if sys.platform == "win32":
    import msvcrt
else:
    import termios


def select_one(prompt: str, choices: list[str], default: int = 0) -> int:
    if not (sys.stdin.isatty() and sys.stderr.isatty()):
        return _fallback(prompt, choices, default)
    if sys.platform == "win32":
        return _select_windows(prompt, choices, default)
    return _select_posix(prompt, choices, default)


def _select_posix(prompt: str, choices: list[str], default: int) -> int:
    fd = sys.stdin.fileno()
    saved = termios.tcgetattr(fd)
    new = termios.tcgetattr(fd)
    new[3] &= ~(termios.ECHO | termios.ICANON)
    cur = default
    _draw_initial(prompt, choices, cur)
    try:
        termios.tcsetattr(fd, termios.TCSADRAIN, new)
        while True:
            key = _read_key_posix()
            if key == "enter":
                return cur
            if key == "ctrl_c":
                raise KeyboardInterrupt
            if key in ("up", "down"):
                cur = (cur + (-1 if key == "up" else 1)) % len(choices)
                _redraw(choices, cur)
    finally:
        termios.tcsetattr(fd, termios.TCSADRAIN, saved)
        sys.stderr.write("\n")


def _select_windows(prompt: str, choices: list[str], default: int) -> int:
    cur = default
    _draw_initial(prompt, choices, cur)
    try:
        while True:
            key = _read_key_windows()
            if key == "enter":
                return cur
            if key == "ctrl_c":
                raise KeyboardInterrupt
            if key in ("up", "down"):
                cur = (cur + (-1 if key == "up" else 1)) % len(choices)
                _redraw(choices, cur)
    finally:
        sys.stderr.write("\n")


def _read_key_posix() -> str:
    b = sys.stdin.read(1)
    if b == "\x03":
        return "ctrl_c"
    if b in ("\r", "\n"):
        return "enter"
    if b == "\x1b" and sys.stdin.read(1) == "[":
        return {"A": "up", "B": "down"}.get(sys.stdin.read(1), "")
    return ""


def _read_key_windows() -> str:
    b = msvcrt.getch()
    if b == b"\x03":
        return "ctrl_c"
    if b in (b"\r", b"\n"):
        return "enter"
    if b in (b"\x00", b"\xe0"):
        return {b"H": "up", b"P": "down"}.get(msvcrt.getch(), "")
    return ""


def _draw_initial(prompt: str, choices: list[str], cur: int) -> None:
    sys.stderr.write(prompt + "\n")
    width = max(len(c) for c in choices)
    for i, c in enumerate(choices):
        marker = " <" if i == cur else ""
        sys.stderr.write(f"  {c:<{width}}{marker}\n")
    sys.stderr.flush()


def _redraw(choices: list[str], cur: int) -> None:
    sys.stderr.write(f"\x1b[{len(choices)}A")
    width = max(len(c) for c in choices)
    for i, c in enumerate(choices):
        marker = " <" if i == cur else ""
        sys.stderr.write(f"\r\x1b[2K  {c:<{width}}{marker}\n")
    sys.stderr.flush()


def _fallback(prompt: str, choices: list[str], default: int) -> int:
    click.echo(prompt, err=True)
    for i, c in enumerate(choices, 1):
        click.echo(f"  {i}. {c}", err=True)
    return (
        click.prompt(
            "Select",
            type=click.IntRange(1, len(choices)),
            default=default + 1,
            err=True,
        )
        - 1
    )

```

